/* Feedback stays separate from registration and finance. RLS enforces ownership. */
let feedbackRows=[],feedbackAccount=null,feedbackLoaded=false,feedbackLoading=false,feedbackError='',feedbackDraft={kind:'suggestion',subject:'',message:''},feedbackFilter='all',feedbackHasMore=false,feedbackBusy=false;
const feedbackKinds={suggestion:'پیشنهاد',criticism:'انتقاد',appreciation:'قدردانی'};
menu.push(['feedback','✉','انتقادات و پیشنهادات']);
function feedbackDate(value){return new Date(value).toLocaleString('fa-IR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tehran'})}
function feedbackReset(){feedbackBusy=false;feedbackRows=[];feedbackLoaded=false;feedbackLoading=false;feedbackError='';feedbackDraft={kind:'suggestion',subject:'',message:''};feedbackAccount=uid;feedbackFilter='all';feedbackHasMore=false}
function feedbackAuthor(row){const s=db.students.find(s=>s.user_id===row.user_id);if(s)return full(s);const r=typeof enrollmentRows!=='undefined'?enrollmentRows.find(r=>r.user_id===row.user_id):null;return r?.details?((r.details.first_name||'')+' '+(r.details.last_name||'')).trim()||'هنرجو':'هنرجو'}
function feedbackList(){const rows=feedbackRows.filter(r=>feedbackFilter!=='new'||r.status==='new');return rows.map(r=>`<article class="feedback-message ${r.status==='new'?'feedback-unread':''}"><div class="feedback-message-top"><span class="badge">${esc(feedbackKinds[r.kind])}</span><span class="feedback-status">${r.status==='new'?'ارسال‌شده · در انتظار مطالعه':'مطالعه‌شده توسط مدیر'}</span></div><h3>${esc(r.subject)}</h3>${admin?`<p class="feedback-author">از طرف ${esc(feedbackAuthor(r))}</p>`:''}<p class="feedback-body">${esc(r.message)}</p><div class="feedback-message-bottom"><time datetime="${esc(r.created_at)}">${esc(feedbackDate(r.created_at))}</time>${admin&&r.status==='new'?`<button type="button" onclick="markFeedbackRead('${r.id}',this)">ثبت به‌عنوان مطالعه‌شده ✓</button>`:''}</div></article>`).join('')||'<div class="feedback-empty"><span aria-hidden="true">✉</span><h3>هنوز پیامی در این بخش نیست</h3><p>پیام‌های ثبت‌شده اینجا نمایش داده می‌شوند.</p></div>'}
views.feedback=function(){if(role!=='student'&&!admin)return '<div class="card">این بخش برای هنرجو و مدیر است.</div>';return title(admin?'صدای هنرجویان':'انتقادات و پیشنهادات',admin?'پیام‌های هنرجویان برای بهبود تجربهٔ آموزش':'با شنیدن تو، بهتر می‌شویم')+`<section class="feedback-intro"><span aria-hidden="true">✦</span><div><h2>${admin?'هر پیام، فرصتی برای بهتر شدن':'صدای تو در پیشرفت هزاردستان اثر دارد'}</h2><p>${admin?'انتقادها و پیشنهادها را بخوان و پس از مطالعه، وضعیتشان را مشخص کن.':'از تجربهٔ کلاس‌ها، خدمات و فضای آموزشگاه برایمان بنویس. پیشنهادها و انتقادهای تو کمک می‌کند با دقت بیشتری خدمت کنیم.'}</p><small>پیام‌ها فقط برای خود هنرجو و مدیر آموزشگاه قابل مشاهده‌اند.</small></div></section><div class="feedback-layout">${!admin?`<section class="card feedback-compose"><h2>پیامت برای مدیر</h2><form id="feedback-form" onsubmit="submitFeedback(event)"><label>نوع پیام<select name="kind" onchange="feedbackDraft.kind=this.value">${Object.entries(feedbackKinds).map(([v,l])=>`<option value="${v}" ${feedbackDraft.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label>موضوع<input name="subject" required minlength="3" maxlength="120" value="${esc(feedbackDraft.subject)}" placeholder="مثلاً پیشنهاد دربارهٔ برنامهٔ کلاس" oninput="feedbackDraft.subject=this.value"></label><label>متن پیام<textarea name="message" required minlength="10" maxlength="3000" rows="7" placeholder="تجربه‌ات چه بود و چه چیزی می‌تواند بهتر شود؟" oninput="feedbackDraft.message=this.value">${esc(feedbackDraft.message)}</textarea></label><p class="feedback-hint">۱۰ تا ۳۰۰۰ کاراکتر · نامت همراه پیام برای مدیر نمایش داده می‌شود.</p><p id="feedback-submit-error" role="alert"></p><button type="submit" class="primary" ${feedbackBusy?'disabled':''}>${feedbackBusy?'در حال ارسال…':'ارسال پیام برای مدیر ↖'}</button><p id="feedback-success" role="status"></p></form></section>`:''}<section class="feedback-inbox"><div class="feedback-inbox-heading"><h2>${admin?'صندوق پیام‌ها':'پیام‌های من'}</h2><button type="button" onclick="loadFeedback()" ${feedbackLoading?'disabled':''}>↻ به‌روزرسانی</button></div>${admin?`<div class="feedback-filters"><button aria-pressed="${feedbackFilter==='all'}" onclick="feedbackFilter='all';render()">همهٔ پیام‌ها</button><button aria-pressed="${feedbackFilter==='new'}" onclick="feedbackFilter='new';render()">خوانده‌نشده‌ها</button></div>`:''}<p role="status">${feedbackLoading?'در حال دریافت پیام‌ها…':''}</p>${feedbackError?'<p class="feedback-error" role="alert">دریافت پیام‌ها انجام نشد. دوباره به‌روزرسانی را بزنید.</p>':''}${feedbackList()}${feedbackHasMore?'<button type="button" onclick="loadFeedback(true)">نمایش پیام‌های قدیمی‌تر</button>':''}</section></div>`};
async function loadFeedback(more=false){if(!uid||(!admin&&role!=='student')||feedbackLoading)return;const account=uid;feedbackLoading=true;feedbackError='';try{const rows=await api('/rest/v1/student_feedback?select=*&order=created_at.desc,id.desc&limit=50&offset='+(more?feedbackRows.length:0));if(uid!==account)return;feedbackRows=more?[...feedbackRows,...rows]:rows;feedbackHasMore=rows.length===50;feedbackLoaded=true}catch(e){if(uid===account)feedbackError=e.message}finally{if(uid===account){feedbackLoading=false;if(page==='feedback')render();refreshFeedbackBadge()}}}
async function submitFeedback(event){event.preventDefault();if(feedbackBusy||role!=='student')return;const f=event.target;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f)),account=uid;data.subject=data.subject.trim();data.message=data.message.trim();const error=document.getElementById('feedback-submit-error');error.textContent='';if(data.subject.length<3||data.message.length<10){error.textContent='موضوع حداقل ۳ و متن پیام حداقل ۱۰ کاراکتر باشد.';return}feedbackBusy=true;f.querySelector('[type=submit]').disabled=true;try{await api('/rest/v1/student_feedback','POST',{...data,user_id:account});if(uid!==account)return;feedbackDraft={kind:'suggestion',subject:'',message:''};await loadFeedback();if(page==='feedback'){render();document.getElementById('feedback-success').textContent='پیامت با موفقیت برای مدیر ثبت شد. ممنون که به بهتر شدن آموزشگاه کمک می‌کنی.'}}catch(e){if(uid===account)error.textContent='ارسال انجام نشد؛ متن پیامت حفظ شده است. دوباره تلاش کن.'}finally{feedbackBusy=false;if(uid===account){const b=document.querySelector('#feedback-form [type=submit]');if(b){b.disabled=false;b.textContent='ارسال پیام برای مدیر ↖'}}}}
async function markFeedbackRead(id,button){if(!admin)return;button.disabled=true;try{await api('/rest/v1/student_feedback?id=eq.'+id,'PATCH',{status:'read',read_at:new Date().toISOString()});await loadFeedback()}catch(e){toast('ثبت وضعیت انجام نشد؛ دوباره تلاش کنید.');button.disabled=false}}
async function refreshFeedbackBadge(){if(!admin||!uid)return;const account=uid;try{const rows=await api('/rest/v1/student_feedback?select=id&status=eq.new&limit=100');if(uid!==account||!admin)return;const b=document.querySelector('#nav [data-feedback-nav]');if(b)b.innerHTML='✉ پیام هنرجویان'+(rows.length?` <span class="feedback-count">${rows.length.toLocaleString('fa-IR')}${rows.length===100?'+':''}</span>`:'')}catch{}}
const feedbackBaseRender=render;render=function(){if(feedbackAccount!==uid)feedbackReset();feedbackBaseRender();if(uid&&(admin||role==='student')){const nav=$('nav');let b=[...nav.querySelectorAll('button')].find(b=>b.getAttribute('onclick')==="go('feedback')");if(b)b.dataset.feedbackNav='true';if(page==='feedback'&&!feedbackLoaded&&!feedbackLoading&&!feedbackError)loadFeedback()}};
const feedbackBaseReload=reload;reload=async function(){await feedbackBaseReload();if(uid&&(admin||role==='student')){if(page==='feedback')await loadFeedback();else refreshFeedbackBadge()}};
setInterval(()=>{if(uid&&admin&&!document.hidden)refreshFeedbackBadge()},60000);
